#!/usr/bin/env python3
"""Generate visuals.csv for ancient_night_video — PART 2 (slides 13-26).

Appends to the CSV written by gen_spine_part1.py. Same 4-column schema.
"""
import csv, os

R = []


def row(slide, moment, text, prompt):
    R.append([f"{slide:02d}", f"{moment:02d}", text, prompt])


