row(13, 12, "People used the phrase the way you'd say lunch —", "[CAVE][THE_ANCESTORS_GROUP] Overhead shot of four figures seated in a loose circle on the umber floor, flat wooden bowls rendered as simple circles before each of them.")
row(13, 13, "something so normal it needed no explanation.", "[CAVE][THE_ANCESTORS_GROUP] Wide shot, the same four figures mid-conversation, one leaning in, gestures rendered as short flat ink strokes, the fire calm and central.")

